export const DEFAULT_FOOD_IMAGE = "https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80";

export function getFoodProductImage(slug: string, fallback?: string): string {
  const normalized = slug.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  return FOOD_IMAGE_MAP[normalized] || fallback || DEFAULT_FOOD_IMAGE;
}


