export const DEFAULT_VEHICLES_IMAGE = "https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=800&q=80";

export function getVehiclesProductImage(slug: string, fallback?: string): string {
  const normalized = slug.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  return VEHICLES_IMAGE_MAP[normalized] || fallback || DEFAULT_VEHICLES_IMAGE;
}


